{
  "title": "LiteLLM on GCP (Cloud Run)",
  "name": "litellm-gcp",
  "description": "Deploys the LiteLLM proxy on GCP: Cloud Run gateway/backend/UI, Cloud SQL with a read replica, Memorystore Redis, a GCS bucket, Secret Manager entries, and an external HTTPS load balancer. Takes ~20-25 minutes on the first apply.",
  "duration": 25,
  "documentation_link": "https://github.com/BerriAI/litellm/blob/main/terraform/litellm/gcp/README.md",
  "collect_project": true,
  "collect_region": true,
  "region_type": "run",
  "region_default": "us-central1",
  "collect_zone": false,
  "custom_settings": [
    {
      "name": "tenant",
      "description": "Tenant slug used as the prefix for every GCP resource the stack creates (e.g. 'acme' produces 'acme-litellm-<env>-gateway'). 1-21 lowercase chars starting with a letter",
      "default": "acme",
      "validation": "^[a-z][a-z0-9-]{0,20}$"
    },
    {
      "name": "env",
      "description": "Environment suffix appended to every resource name (e.g. 'stage', 'prod', 'dev'). 1-9 lowercase chars starting with a letter",
      "default": "stage",
      "validation": "^[a-z][a-z0-9-]{0,8}$"
    },
    {
      "name": "image_tag",
      "description": "Tag for the four litellm-* images (gateway, backend, ui, migrations). Bump together when bumping LiteLLM",
      "default": "v1.106.4"
    },
    {
      "name": "image_registry",
      "description": "Artifact Registry path prefix for the four litellm-* images. Format: <region>-docker.pkg.dev/<project>/litellm/berriai, pointing at the remote repo you created above. Substitute BOTH REGION and PROJECT_ID in the default to match the AR repo you just created (REGION must match the region you picked above). The ghcr.io/berriai default in the module does NOT work; Cloud Run rejects ghcr.io URIs at apply time",
      "default": "REGION-docker.pkg.dev/PROJECT_ID/litellm/berriai"
    },
    {
      "name": "allow_plaintext_lb",
      "description": "Skip TLS on the load balancer (HTTP-only). Set true for trial/dev. For production, leave false and add lb_domains to terraform.tfvars after the first apply",
      "default": "true",
      "options": ["true", "false"]
    }
  ]
}

# Plan-only coverage for the opt-in collector sidecar on the gateway Cloud
# Run service. `mock_provider` keeps this offline: no GCP credentials, no API
# calls. Run from terraform/litellm/gcp with `terraform test`.

mock_provider "google" {}
mock_provider "google-beta" {}
mock_provider "random" {}

variables {
  project_id         = "acme-test"
  region             = "us-central1"
  tenant             = "acme"
  env                = "test"
  allow_plaintext_lb = true
}

run "disabled_by_default_leaves_the_service_untouched" {
  command = plan

  assert {
    condition     = [for c in google_cloud_run_v2_service.gateway[0].template[0].containers : c.name] == ["gateway"]
    error_message = "The gateway service must stay single-container unless collector_enabled is set."
  }

  assert {
    condition = !anytrue([
      for e in google_cloud_run_v2_service.gateway[0].template[0].containers[0].env : startswith(e.name, "LITELLM_COLLECTOR_")
    ])
    error_message = "No LITELLM_COLLECTOR_* env may reach the gateway while the sidecar is disabled."
  }
}

run "enabled_adds_a_sidecar_that_shares_the_gateway_transport" {
  command = plan

  variables {
    collector_enabled        = true
    collector_port           = 4321
    collector_buffer_size    = 250
    collector_on_unavailable = "drop"
    collector_cpu            = "500m"
    collector_memory         = "1Gi"
    gateway_extra_env        = { OPENAI_API_BASE = "https://example.invalid" }
    gateway_extra_secrets    = { OPENAI_API_KEY = "[REDACTED]" }
  }

  assert {
    condition     = [for c in google_cloud_run_v2_service.gateway[0].template[0].containers : c.name] == ["gateway", "spend-collector"]
    error_message = "Enabling the sidecar must append a spend-collector container after the gateway container."
  }

  assert {
    condition = alltrue([
      for c in google_cloud_run_v2_service.gateway[0].template[0].containers : (
        { for e in c.env : e.name => e.value }["LITELLM_COLLECTOR_ENABLED"] == "true" &&
        { for e in c.env : e.name => e.value }["LITELLM_COLLECTOR_ADDRESS"] == "tcp://127.0.0.1:4321" &&
        { for e in c.env : e.name => e.value }["LITELLM_COLLECTOR_BUFFER_SIZE"] == "250" &&
        { for e in c.env : e.name => e.value }["LITELLM_COLLECTOR_ON_UNAVAILABLE"] == "drop" &&
        { for e in c.env : e.name => e.value }["LITELLM_COLLECTOR_DRAIN_TIMEOUT_SECONDS"] == "10"
      )
    ])
    error_message = "Gateway and sidecar must agree on the loopback address and the collector knobs."
  }

  assert {
    condition = (
      google_cloud_run_v2_service.gateway[0].template[0].containers[1].image == local.gateway_image &&
      google_cloud_run_v2_service.gateway[0].template[0].containers[1].command == tolist(["sh", "-c"]) &&
      endswith(google_cloud_run_v2_service.gateway[0].template[0].containers[1].args[0], " && exec python -m litellm.proxy.collector") &&
      strcontains(google_cloud_run_v2_service.gateway[0].template[0].containers[1].args[0], "export DATABASE_URL=") &&
      strcontains(google_cloud_run_v2_service.gateway[0].template[0].containers[1].args[0], "REDIS_SSL_CA_CERTS") &&
      { for e in google_cloud_run_v2_service.gateway[0].template[0].containers[1].env : e.name => e.value }["LITELLM_JOB_ROLE"] == "collector"
    )
    error_message = "The sidecar must run litellm.proxy.collector from the gateway image with the same Redis CA + DATABASE_URL bootstrap as the gateway."
  }

  assert {
    condition = (
      length(google_cloud_run_v2_service.gateway[0].template[0].containers[1].ports) == 0 &&
      google_cloud_run_v2_service.gateway[0].template[0].containers[1].resources[0].limits.cpu == "500m" &&
      google_cloud_run_v2_service.gateway[0].template[0].containers[1].resources[0].limits.memory == "1Gi"
    )
    error_message = "The sidecar must not claim the ingress port and must carry its own resource limits."
  }

  assert {
    condition = (
      { for e in google_cloud_run_v2_service.gateway[0].template[0].containers[1].env : e.name => e.value }["OPENAI_API_BASE"] == "https://example.invalid" &&
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[1].env : e.name], "DATABASE_HOST") &&
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[1].env : e.name], "REDIS_HOST") &&
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[1].env : e.name if length(e.value_source) > 0], "LITELLM_MASTER_KEY") &&
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[1].env : e.name if length(e.value_source) > 0], "DATABASE_PASSWORD") &&
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[1].env : e.name if length(e.value_source) > 0], "OPENAI_API_KEY")
    )
    error_message = "The sidecar must receive the gateway's database, Redis, and Secret Manager env plus gateway_extra_env / gateway_extra_secrets."
  }
}

run "coexists_with_the_metrics_sidecars" {
  command = plan

  variables {
    collector_enabled    = true
    gateway_metrics_port = 4001
  }

  assert {
    condition     = [for c in google_cloud_run_v2_service.gateway[0].template[0].containers : c.name] == ["gateway", "metrics", "collector", "spend-collector"]
    error_message = "The spend collector must keep its own container name next to the GMP metrics collector."
  }

  assert {
    condition = (
      { for e in google_cloud_run_v2_service.gateway[0].template[0].containers[0].env : e.name => e.value }["PROMETHEUS_MULTIPROC_DIR"] == local.metrics_multiproc_dir &&
      { for e in google_cloud_run_v2_service.gateway[0].template[0].containers[0].env : e.name => e.value }["LITELLM_COLLECTOR_ENABLED"] == "true"
    )
    error_message = "The gateway container must keep both the metrics and the collector env when both sidecars are on."
  }
}

run "sidecars_must_not_share_a_loopback_port" {
  command = plan

  variables {
    collector_enabled    = true
    collector_port       = 4001
    gateway_metrics_port = 4001
  }

  expect_failures = [
    google_cloud_run_v2_service.gateway,
  ]
}

run "collector_cannot_take_the_metrics_sidecar_health_port" {
  command = plan

  variables {
    collector_enabled = true
    collector_port    = 13133
  }

  expect_failures = [
    var.collector_port,
  ]
}

run "proxy_config_is_mounted_into_the_sidecar_too" {
  command = plan

  variables {
    collector_enabled = true
    proxy_config      = { model_list = [] }
  }

  assert {
    condition = alltrue([
      for c in google_cloud_run_v2_service.gateway[0].template[0].containers : (
        [for m in c.volume_mounts : m.name] == [local.proxy_config_volume] &&
        contains([for e in c.env : e.name], "CONFIG_FILE_PATH")
      )
    ])
    error_message = "Both containers must mount the proxy-config GCS volume and point CONFIG_FILE_PATH at it."
  }
}

# Plan-only coverage for the in-container PgBouncer knobs on the gateway
# service. `mock_provider` keeps this offline: no GCP credentials, no API
# calls, no resources. Run from terraform/litellm/gcp with `terraform test`.

mock_provider "google" {
  mock_resource "google_redis_instance" {
    defaults = {
      host = "10.0.0.4"
      port = 6379
      server_ca_certs = [{
        cert = "-----BEGIN CERTIFICATE-----\nmock\n-----END CERTIFICATE-----"
      }]
    }
  }
}

mock_provider "google-beta" {}
mock_provider "random" {}

variables {
  project_id         = "test-project"
  tenant             = "tenant"
  env                = "test"
  allow_plaintext_lb = true
  image_registry     = "us-central1-docker.pkg.dev/test-project/litellm"
}

run "pool_off_by_default" {
  command = plan

  assert {
    condition     = length(local.gateway_pool_env) == 0
    error_message = "The gateway must get no LITELLM_PGBOUNCER_* env unless gateway_connection_pool_enabled is set."
  }

  assert {
    condition = !anytrue([
      for e in google_cloud_run_v2_service.gateway[0].template[0].containers[0].env : startswith(e.name, "LITELLM_PGBOUNCER_")
    ])
    error_message = "The gateway service must carry no LITELLM_PGBOUNCER_* env by default."
  }
}

run "pool_enabled_renders_the_three_vars_with_configured_sizes" {
  command = plan

  variables {
    gateway_num_workers             = 4
    gateway_connection_pool_enabled = true
    gateway_pool_max_db_connections = 8
    gateway_pool_max_client_conn    = 250
  }

  assert {
    condition = alltrue([
      length(local.gateway_pool_env) == 3,
      local.gateway_pool_env[0].name == "LITELLM_PGBOUNCER_ENABLED" && local.gateway_pool_env[0].value == "true",
      local.gateway_pool_env[1].name == "LITELLM_PGBOUNCER_MAX_DB_CONNECTIONS" && local.gateway_pool_env[1].value == "8",
      local.gateway_pool_env[2].name == "LITELLM_PGBOUNCER_MAX_CLIENT_CONN" && local.gateway_pool_env[2].value == "250",
    ])
    error_message = "The pool env must carry the enabled flag and the configured sizes as strings."
  }

  assert {
    condition = alltrue([
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[0].env : e.name], "LITELLM_PGBOUNCER_ENABLED"),
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[0].env : e.name], "LITELLM_PGBOUNCER_MAX_DB_CONNECTIONS"),
      contains([for e in google_cloud_run_v2_service.gateway[0].template[0].containers[0].env : e.name], "LITELLM_PGBOUNCER_MAX_CLIENT_CONN"),
    ])
    error_message = "The gateway service must receive all three LITELLM_PGBOUNCER_* env vars."
  }

  assert {
    condition = !anytrue(concat(
      [for e in google_cloud_run_v2_service.backend[0].template[0].containers[0].env : startswith(e.name, "LITELLM_PGBOUNCER_")],
      [for e in google_cloud_run_v2_job.migrations[0].template[0].template[0].containers[0].env : startswith(e.name, "LITELLM_PGBOUNCER_")],
    ))
    error_message = "The backend service and the migrations job must keep their direct database connection."
  }
}

run "collector_sidecar_gets_the_same_pool_env_as_the_gateway" {
  command = plan

  variables {
    collector_enabled               = true
    gateway_connection_pool_enabled = true
    gateway_pool_max_db_connections = 8
    gateway_pool_max_client_conn    = 250
  }

  assert {
    condition = alltrue([
      for c in google_cloud_run_v2_service.gateway[0].template[0].containers : (
        { for e in c.env : e.name => e.value }["LITELLM_PGBOUNCER_ENABLED"] == "true" &&
        { for e in c.env : e.name => e.value }["LITELLM_PGBOUNCER_MAX_DB_CONNECTIONS"] == "8" &&
        { for e in c.env : e.name => e.value }["LITELLM_PGBOUNCER_MAX_CLIENT_CONN"] == "250"
      ) if c.name == "spend-collector"
    ]) && length([for c in google_cloud_run_v2_service.gateway[0].template[0].containers : c.name if c.name == "spend-collector"]) == 1
    error_message = "The spend-collector sidecar must carry the same three LITELLM_PGBOUNCER_* vars as the gateway so its Prisma connects to the instance-local pool."
  }
}

run "collector_sidecar_gets_no_pool_env_when_the_pool_is_off" {
  command = plan

  variables {
    collector_enabled = true
  }

  assert {
    condition = !anytrue(flatten([
      for c in google_cloud_run_v2_service.gateway[0].template[0].containers : [
        for e in c.env : startswith(e.name, "LITELLM_PGBOUNCER_")
      ] if c.name == "spend-collector"
    ])) && length([for c in google_cloud_run_v2_service.gateway[0].template[0].containers : c.name if c.name == "spend-collector"]) == 1
    error_message = "The spend-collector sidecar must get no LITELLM_PGBOUNCER_* env unless gateway_connection_pool_enabled is set."
  }
}

run "pool_enabled_uses_the_module_default_sizes" {
  command = plan

  variables {
    gateway_connection_pool_enabled = true
  }

  assert {
    condition = alltrue([
      length(local.gateway_pool_env) == 3,
      local.gateway_pool_env[1].name == "LITELLM_PGBOUNCER_MAX_DB_CONNECTIONS" && local.gateway_pool_env[1].value == "20",
      local.gateway_pool_env[2].name == "LITELLM_PGBOUNCER_MAX_CLIENT_CONN" && local.gateway_pool_env[2].value == "1000",
    ])
    error_message = "The pool env must fall back to the module defaults of 20 upstream and 1000 client connections."
  }
}

run "gateway_starts_through_the_pool_aware_launcher" {
  command = plan

  variables {
    gateway_num_workers = 4
  }

  assert {
    condition = alltrue([
      strcontains(local.gateway_launch_cmd, "exec python -m gateway.launch --host 0.0.0.0 --port 4000 --workers 4"),
      strcontains(local.gateway_launch_cmd, "exec ddtrace-run python -m gateway.launch --host 0.0.0.0 --port 4000 --workers 4"),
      !strcontains(local.gateway_launch_cmd, "uvicorn gateway.main:app"),
      endswith(google_cloud_run_v2_service.gateway[0].template[0].containers[0].args[0], local.gateway_launch_cmd),
    ])
    error_message = "The gateway must start through gateway.launch (with and without ddtrace) so the pooler starts once before uvicorn forks the workers."
  }

  assert {
    condition     = strcontains(local.backend_launch_cmd, "uvicorn backend.main:app")
    error_message = "The backend has no workers to share a pooler and keeps starting uvicorn directly."
  }
}

run "pool_sizes_below_one_fail_at_plan" {
  command = plan

  variables {
    gateway_connection_pool_enabled = true
    gateway_pool_max_db_connections = 0
    gateway_pool_max_client_conn    = 0
  }

  expect_failures = [
    var.gateway_pool_max_db_connections,
    var.gateway_pool_max_client_conn,
  ]
}

